window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-06b92c0c5cf935f5"]={"versions": [{"id": "FIG-06b92c0c5cf935f5", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Datagramm- und Bit-Layout-Diagramm zur Definition der Serialisierungs- und Header-Struktur des AUTOSAR E2E Profile 11 Variant A im Kontext des E2E-Protokolls (End-to-End Communication Protection) für Classic und Adaptive Platform. Das Diagramm spezifiziert die Zuordnung der Schutzfelder innerhalb der ersten zwei Bytes eines geschützten Datenstroms.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die tabellarische Struktur gliedert sich in folgende Entitäten und Adressierungszeilen:</p>\n<ul class=\"fig-list\">\n<li><strong>Byte Order</strong>: Kennzeichnung der Byte-Positionen <code>0</code> und <code>1</code>.</li>\n<li><strong>Transmission Order</strong>: Fortlaufende Nummerierung der Übertragungsreihenfolge der Bits von <code>0</code> bis <code>15</code>.</li>\n<li><strong>Bit Order</strong>: Kennzeichnung der Bit-Wertigkeiten bzw. logischen Bit-Positionen:</li>\n<li>Byte 0 (Transmission Order 0–7): Bits <code>7</code> bis <code>0</code> (MSB-first innerhalb des Bytes).</li>\n<li>Byte 1 (Transmission Order 8–15): Dargestellt mit den Bit-Labels <code>15</code>, <code>14</code>, <code>12</code>, <code>12</code>, <code>11</code>, <code>10</code>, <code>9</code>, <code>8</code>.</li>\n<li><strong>Nutzdaten- / Header-Felder (Zeile 0)</strong>:</li>\n<li><code>E2E CRC</code>: Belegt Byte 0 (Transmission Order 0–7, 8 Bit Prüfsumme).</li>\n<li>Unbelegter Zwischenbereich / Datenbereich: Transmission Order 8–11 (oberes Nibble von Byte 1).</li>\n<li><code>Counter</code>: Belegt die Transmission Order 12–15 (unteres Nibble von Byte 1, 4 Bit Zähler).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicher- und Serialisierungs-Layout; kein dynamischer Sequenzablauf dargestellt. Der Datenstrom wird byteweise übertragen, beginnend bei Byte 0 mit der vollständigen 8-Bit-Prüfsumme <code>E2E CRC</code>, gefolgt von Byte 1, dessen niederwertige 4 Bits den 4-Bit <code>Counter</code> transportieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation des Headers für E2E Profile 11 Variante A:</p>\n<ul class=\"fig-list\">\n<li>Offset 0 (Byte 0, 8 Bit): <code>E2E CRC</code> zur Erkennung von Übertragungs- und Bitfehlern.</li>\n<li>Offset 1 (Byte 1, Bits 12–15 der Übertragungsreihenfolge): 4-Bit <code>Counter</code> zur Erkennung von Wiederholungs-, Verlust- und Sequenzfehlern.</li>\n<li>Entwickler müssen bei der Serialisierung/Deserialisierung die Big-Endian/MSB-first-Zuordnung sowie den Satzfehler in der Beschriftungszeile „Bit Order“ bei Byte 1 (doppelte <code>12</code>, fehlende <code>13</code>) berücksichtigen, wobei die Transmission Order 0–15 die exakte Bitfolge im Datenstrom vorgibt.</li>\n</ul>"}, {"id": "FIG-353cd968a0e3fe97", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Datagramm- und Bit-Layout-Diagramm zur Definition der Serialisierungs- und Header-Struktur des AUTOSAR E2E Profile 11 Variant A im Kontext des E2E-Protokolls (End-to-End Communication Protection) für Classic und Adaptive Platform. Das Diagramm spezifiziert die Zuordnung der Schutzfelder innerhalb der ersten zwei Bytes eines geschützten Datenstroms.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die tabellarische Struktur gliedert sich in folgende Entitäten und Adressierungszeilen:</p>\n<ul class=\"fig-list\">\n<li><strong>Byte Order</strong>: Kennzeichnung der Byte-Positionen <code>0</code> und <code>1</code>.</li>\n<li><strong>Transmission Order</strong>: Fortlaufende Nummerierung der Übertragungsreihenfolge der Bits von <code>0</code> bis <code>15</code>.</li>\n<li><strong>Bit Order</strong>: Kennzeichnung der Bit-Wertigkeiten bzw. logischen Bit-Positionen:</li>\n<li>Byte 0 (Transmission Order 0–7): Bits <code>7</code> bis <code>0</code> (MSB-first innerhalb des Bytes).</li>\n<li>Byte 1 (Transmission Order 8–15): Dargestellt mit den Bit-Labels <code>15</code>, <code>14</code>, <code>12</code>, <code>12</code>, <code>11</code>, <code>10</code>, <code>9</code>, <code>8</code>.</li>\n<li><strong>Nutzdaten- / Header-Felder (Zeile 0)</strong>:</li>\n<li><code>E2E CRC</code>: Belegt Byte 0 (Transmission Order 0–7, 8 Bit Prüfsumme).</li>\n<li>Unbelegter Zwischenbereich / Datenbereich: Transmission Order 8–11 (oberes Nibble von Byte 1).</li>\n<li><code>Counter</code>: Belegt die Transmission Order 12–15 (unteres Nibble von Byte 1, 4 Bit Zähler).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicher- und Serialisierungs-Layout; kein dynamischer Sequenzablauf dargestellt. Der Datenstrom wird byteweise übertragen, beginnend bei Byte 0 mit der vollständigen 8-Bit-Prüfsumme <code>E2E CRC</code>, gefolgt von Byte 1, dessen niederwertige 4 Bits den 4-Bit <code>Counter</code> transportieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation des Headers für E2E Profile 11 Variante A:</p>\n<ul class=\"fig-list\">\n<li>Offset 0 (Byte 0, 8 Bit): <code>E2E CRC</code> zur Erkennung von Übertragungs- und Bitfehlern.</li>\n<li>Offset 1 (Byte 1, Bits 12–15 der Übertragungsreihenfolge): 4-Bit <code>Counter</code> zur Erkennung von Wiederholungs-, Verlust- und Sequenzfehlern.</li>\n<li>Entwickler müssen bei der Serialisierung/Deserialisierung die Big-Endian/MSB-first-Zuordnung sowie den Satzfehler in der Beschriftungszeile „Bit Order“ bei Byte 1 (doppelte <code>12</code>, fehlende <code>13</code>) berücksichtigen, wobei die Transmission Order 0–15 die exakte Bitfolge im Datenstrom vorgibt.</li>\n</ul>"}, {"id": "FIG-c1cd1acd85635c2b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Datagramm- und Bit-Layout-Diagramm zur Definition der Serialisierungs- und Header-Struktur des AUTOSAR E2E Profile 11 Variant A im Kontext des E2E-Protokolls (End-to-End Communication Protection) für Classic und Adaptive Platform. Das Diagramm spezifiziert die Zuordnung der Schutzfelder innerhalb der ersten zwei Bytes eines geschützten Datenstroms.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die tabellarische Struktur gliedert sich in folgende Entitäten und Adressierungszeilen:</p>\n<ul class=\"fig-list\">\n<li><strong>Byte Order</strong>: Kennzeichnung der Byte-Positionen <code>0</code> und <code>1</code>.</li>\n<li><strong>Transmission Order</strong>: Fortlaufende Nummerierung der Übertragungsreihenfolge der Bits von <code>0</code> bis <code>15</code>.</li>\n<li><strong>Bit Order</strong>: Kennzeichnung der Bit-Wertigkeiten bzw. logischen Bit-Positionen:</li>\n<li>Byte 0 (Transmission Order 0–7): Bits <code>7</code> bis <code>0</code> (MSB-first innerhalb des Bytes).</li>\n<li>Byte 1 (Transmission Order 8–15): Dargestellt mit den Bit-Labels <code>15</code>, <code>14</code>, <code>12</code>, <code>12</code>, <code>11</code>, <code>10</code>, <code>9</code>, <code>8</code>.</li>\n<li><strong>Nutzdaten- / Header-Felder (Zeile 0)</strong>:</li>\n<li><code>E2E CRC</code>: Belegt Byte 0 (Transmission Order 0–7, 8 Bit Prüfsumme).</li>\n<li>Unbelegter Zwischenbereich / Datenbereich: Transmission Order 8–11 (oberes Nibble von Byte 1).</li>\n<li><code>Counter</code>: Belegt die Transmission Order 12–15 (unteres Nibble von Byte 1, 4 Bit Zähler).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicher- und Serialisierungs-Layout; kein dynamischer Sequenzablauf dargestellt. Der Datenstrom wird byteweise übertragen, beginnend bei Byte 0 mit der vollständigen 8-Bit-Prüfsumme <code>E2E CRC</code>, gefolgt von Byte 1, dessen niederwertige 4 Bits den 4-Bit <code>Counter</code> transportieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation des Headers für E2E Profile 11 Variante A:</p>\n<ul class=\"fig-list\">\n<li>Offset 0 (Byte 0, 8 Bit): <code>E2E CRC</code> zur Erkennung von Übertragungs- und Bitfehlern.</li>\n<li>Offset 1 (Byte 1, Bits 12–15 der Übertragungsreihenfolge): 4-Bit <code>Counter</code> zur Erkennung von Wiederholungs-, Verlust- und Sequenzfehlern.</li>\n<li>Entwickler müssen bei der Serialisierung/Deserialisierung die Big-Endian/MSB-first-Zuordnung sowie den Satzfehler in der Beschriftungszeile „Bit Order“ bei Byte 1 (doppelte <code>12</code>, fehlende <code>13</code>) berücksichtigen, wobei die Transmission Order 0–15 die exakte Bitfolge im Datenstrom vorgibt.</li>\n</ul>"}], "trans": [{"from": "FIG-06b92c0c5cf935f5", "to": "FIG-353cd968a0e3fe97", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-353cd968a0e3fe97", "to": "FIG-c1cd1acd85635c2b", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
